const upsertServiceLogo = `-- name: UpsertServiceLogo :exec
insert into service_logos (service_id, content_type, image_data)
select
    services.id,
    ?1 as content_type,
    ?2   as image_data
from services
where services.public_id = ?3
on conflict (service_id) do update set
    content_type = excluded.content_type,
    image_data = excluded.image_data,
    updated_at = strftime('%s', 'now')
`

type UpsertServiceLogoParams struct {
	ContentType string `json:"content_type"`
	ImageData   []byte `json:"image_data"`
	PublicID    string `json:"public_id"`
}

func (q *Queries) UpsertServiceLogo(ctx context.Context, arg UpsertServiceLogoParams) error {
	_, err := q.db.ExecContext(ctx, upsertServiceLogo, arg.ContentType, arg.ImageData, arg.PublicID)
	return err
}
